/**
 * Python's `sum()` (ints exact, then floats compensated, ints added plainly once a float was
 * seen, `OverflowError` for a huge int next to a float), Python's code-point string order and
 * `bytes` order, and the 4096-code-point scan prefix: keys again generated by the Python plugin.
 */
const PYTHON_SUM_AND_ORDER: [string, () => unknown, string][] = [
  ["[0.5, 2 ** 53, -(2 ** 53), -0.5]", () => [0.5, 2 ** 53, -(2 ** 53), -0.5], "list|any_neg|elem:mixed|len:2-10|order:unsorted"],
  ["[0.1, 0.2, -0.3]", () => [0.1, 0.2, -0.3], "list|any_neg|elem:float|len:2-10|order:unsorted"],
  ["[0.1, 0.2, -0.3, 2 ** 64, -(2 ** 64)]", () => [0.1, 0.2, -0.3, 2 ** 64, -(2 ** 64)], "list|any_neg|elem:mixed|len:2-10|order:unsorted|sum_zero"],
  ["[2 ** 64, -(2 ** 64), 0.1, 0.2, -0.3]", () => [2 ** 64, -(2 ** 64), 0.1, 0.2, -0.3], "list|any_neg|elem:mixed|len:2-10|order:unsorted"],
  ["[1n, -1]", () => [1n, -1], "list|any_neg|elem:int|len:2-10|order:reverse|sum_zero"],
  ["[10n ** 400n, 0.5]", () => [10n ** 400n, 0.5], "list|elem:mixed|len:2-10|order:reverse"],
  ["[1, 1e100, 1, -1e100]", () => [1, 1e100, 1, -1e100], "list|any_neg|dups|elem:int|len:2-10|order:unsorted"],
  ["[2.5, -2, -0.5]", () => [2.5, -2, -0.5], "list|any_neg|elem:mixed|len:2-10|order:unsorted|sum_zero"],
  ['["\\uffff", "\\u{1F600}"]', () => ["\uffff", "\u{1F600}"], "list|elem:str|len:2-10|order:sorted"],
  ['["\\u{1F600}", "\\uffff"]', () => ["\u{1F600}", "\uffff"], "list|elem:str|len:2-10|order:reverse"],
  ["[u8([1]), u8([2])]", () => [new Uint8Array([1]), new Uint8Array([2])], "list|elem:bytes|len:2-10|order:sorted"],
  ["[u8([2]), u8([1, 0])]", () => [new Uint8Array([2]), new Uint8Array([1, 0])], "list|elem:bytes|len:2-10|order:reverse"],
  ["[u8([1, 2]), u8([1, 2])]", () => [new Uint8Array([1, 2]), new Uint8Array([1, 2])], "list|dups|elem:bytes|len:2-10|order:sorted"],
  ["[u8([1]), u8([1, 0])]", () => [new Uint8Array([1]), new Uint8Array([1, 0])], "list|elem:bytes|len:2-10|order:sorted"],
  ['"\\u{1F600}".repeat(4095) + "1"', () => "\u{1F600}".repeat(4095) + "1", "str|digits|len:>1000|unicode"],
  ['"\\u{1F600}".repeat(4096) + "1"', () => "\u{1F600}".repeat(4096) + "1", "str|len:>1000|unicode"],
];

/** The grammar's rule for an `obj:` type token (`coverset_model.shape_keys`): printable, no blank, no `|`. */
function validObjToken(token: string): boolean {
  return /^obj:[^|]+$/u.test(token) && !/[\s\p{C}\p{Z}]/u.test(token) && token.length <= 512;
}

const STRING_KINDS: [string, string | null][] = [
  ["alice@example.com", "email/plain"],
  ["bob@eng.acme.com", "email/multi-label-domain"],
  ["carol@example.co.uk", "email/plain"],
  ["dave@eng.example.co.uk", "email/multi-label-domain"],
  ["d+tag@x.io", "email/plus-tag"],
  ["Eve@Example.com", "email/uppercase"],
  ["josé@example.com", "email/idn"],
  ["x@xn--bcher-kva.example", "email/idn"],
  ["1h30m", "quantity/multi-unit"],
  ["100ms", "quantity/multi-letter-unit"],
  ["1.5h", "quantity/decimal"],
  ["-5m", "quantity/signed"],
  ["1hx", "quantity/trailing-garbage"],
  ["5m", "quantity/single-unit"],
  ["10 apples", "quantity/multi-letter-unit"],
  ["3 h!", "quantity/trailing-garbage"],
  ["42", "numeric"],
  ["-1.5e3", "numeric"],
  ["2026-10-11", "iso-date"],
  ["2026-10-11T08:00:00Z", "iso-date"],
  ["https://example.com/a?b=1", "url"],
  ["hello world", null],
];

describe("shapeKey", () => {
  it.each(SAME_AS_PYTHON)("%s", (_label, make, key) => {
    expect(shapeKey(make())).toBe(key);
  });

  it.each(PYTHON_SUM_AND_ORDER)("sums and orders like Python: %s", (_label, make, key) => {
    expect(shapeKey(make())).toBe(key);
  });

  it("sums exactly like CPython 3.13 on hand-picked edge cases", () => {
    expect(pythonSum([0.5, 2 ** 53, -(2 ** 53), -0.5])).toBe(-0.5);
    expect(pythonSum([2 ** 63, -(2 ** 63), 1])).toBe(1n);
    expect(pythonSum([10n ** 400n, 0.5])).toBeNull();
    expect(pythonSum([0.5, 10n ** 400n])).toBeNull();
    // Integral numbers are ints, so 1e308 is the int 10**308-ish: exact until the float overflows.
    expect(pythonSum([1e308, 1e308, -1e308])).toBe(BigInt(1e308));
    expect(pythonSum([0.5, 1e308, 1e308])).toBe(Infinity);
    expect(pythonSum([])).toBe(0);
  });

  it("maps integral numbers to int, as the specification says", () => {
    expect(shapeKey(-0)).toBe("int|zero");
    expect(shapeKey(1.0)).toBe("int|pos");
    expect(shapeKey([0.5, -0.5])).toBe("list|any_neg|elem:float|len:2-10|order:reverse|sum_zero");
  });

  it("names class instances by their class, and plain objects as dicts", () => {
    class Money {
      cents = 1;
    }
    expect(shapeKey(new Money())).toBe("obj:Money");
    expect(shapeKey(Object.create(null))).toBe("dict|len:0");
    expect(shapeKey(new Date(0))).toBe("obj:Date");
    expect(shapeKey(() => 1)).toBe("obj:Function");
    expect(shapeKey(Symbol("s"))).toBe("obj:Symbol");
    expect(shapeKey(Buffer.from("abc"))).toBe("bytes|len:2-10");
    expect(shapeKey(new ArrayBuffer(4))).toBe("bytes|len:2-10");
    expect(shapeKey([new Money(), new Money()])).toBe("list|elem:obj:Money|len:2-10|order:n/a");
  });

  it("treats subclasses of builtin containers as objects", () => {
    class Bag extends Array<number> {}
    class Registry extends Map<string, number> {}
    expect(shapeKey(new Bag())).toBe("obj:Bag");
    expect(shapeKey(new Registry())).toBe("obj:Registry");
  });

  it("never runs user code: getters, toString, valueOf, proxies, iterators", () => {
    const calls: string[] = [];
    const record = (name: string) => () => {
      calls.push(name);
      return 1;
    };
    const tricky = { toString: record("toString"), valueOf: record("valueOf") };
    Object.defineProperty(tricky, "lazy", { get: record("getter"), enumerable: true });
    const arr = [1, 2];
    Object.defineProperty(arr, 0, { get: record("index getter") });
    const proxy = new Proxy({}, {
      get: record("proxy get"),
      ownKeys: () => (calls.push("proxy ownKeys"), []),
      getPrototypeOf: () => (calls.push("proxy getPrototypeOf"), Object.prototype),
    });
    const map = new Map([[1, 2]]);
    map[Symbol.iterator] = record("map iterator") as never;
    const set = new Set([1]);
    set.values = record("set values") as never;
    expect(shapeKey(tricky)).toBe("dict|elem:mixed|key:str|len:2-10");
    expect(shapeKey(arr)).toBe("list|elem:mixed|len:2-10|order:n/a");
    expect(shapeKey(proxy)).toBe("obj:Proxy");
    expect(shapeKey(map)).toBe("dict|elem:int|key:int|len:1");
    expect(shapeKey(set)).toBe("set|elem:int|len:1");
    expect(shapeKey([tricky, proxy])).toBe("list|elem:mixed|len:2-10|order:n/a");
    expect(calls).toEqual([]);
  });

  it("never reaches a trap of a proxied prototype or class (recording proxy, zero traps)", () => {
    const traps: string[] = [];
    const recording = <T extends object>(target: T): T =>
      new Proxy(target, new Proxy({}, { get: (_t, trap) => (...args: unknown[]) => (traps.push(String(trap)), (Reflect as any)[trap](...args)) }));
    class Foo {
      a = 1;
      m(): number {
        return this.a;
      }
      static make(): Foo {
        return new Foo();
      }
    }
    const protoProxy = recording(Foo.prototype);
    const viaProxyProto = Object.create(protoProxy) as object;
    const ProxiedFoo = recording(Foo);
    class Sub extends ProxiedFoo {}
    const sub = new Sub(); // runs the construct trap: the test's doing, not the recorder's
    traps.length = 0;
    expect(shapeKey(viaProxyProto)).toBe("obj:Proxy");
    expect(shapeKey([viaProxyProto, viaProxyProto])).toBe("list|elem:obj:Proxy|len:2-10|order:n/a");
    expect(exampleRepr("xs", [viaProxyProto])).toBe("[<Proxy>]");
    expect(shapeKey(ProxiedFoo)).toBe("obj:Function");
    expect(shapeKey(sub)).toBe("obj:Sub");
    const recorder = new Recorder();
    recorder.setTest("t");
    const spec = '{"p":[]}';
    recorder.leave(recorder.enter("src/a.ts", 0, "Foo.make", 1, spec, 1 | 16, [], ProxiedFoo), 1);
    recorder.leave(recorder.enter("src/a.ts", 1, "Foo.m", 2, spec, 1, [], sub), 1);
    recorder.leave(recorder.enter("src/a.ts", 1, "Foo.m", 2, spec, 1, [], viaProxyProto), 1);
    recorder.leave(recorder.enter("src/a.ts", 2, "Foo.constructor", 3, spec, 1 | 2, [], Sub), undefined);
    const receivers = recorder.dump().obs.filter((o) => o.p === "<receiver>").map((o) => o.s);
    expect(receivers).toEqual(["obj:Proxy", "obj:Sub", "obj:Proxy", "obj:Sub"]);
    expect(recorder.errors).toBe(0);
    expect(traps).toEqual([]);
  });

  it("writes obj: tokens the grammar accepts (blanks, |, format characters, long names)", () => {
    const named = (name: string) => ({ [name]: class {} })[name]!;
    const odd = ["A\u200dB", "a b|c", "tab\tname", "x".repeat(600), "\u2028", ""];
    for (const name of odd) {
      const Cls = named(name);
      Object.defineProperty(Cls, "name", { value: name });
      const token = shapeKey(new Cls());
      expect(validObjToken(token), JSON.stringify(token)).toBe(true);
      expect(shapeKey({ k: new Cls(), j: new Cls() }).length).toBeLessThanOrEqual(512);
    }
    expect(safeName("A\u200dB")).toBe("A_B");
    // A class the recorder learnt from a path with a space and a qualname with | and a dot key.
    class Cart {
      m(): void {}
    }
    const recorder = new Recorder();
    recorder.setTest("t");
    recorder.leave(recorder.enter("src/my dir/c|art.ts", 0, "api.my key|x.Cart.m", 1, '{"p":[]}', 1, [], new Cart()), undefined);
    const token = shapeKey(new Cart());
    expect(token).toBe("obj:src.my_dir.c_art.api.my_key_x.Cart");
    expect(validObjToken(token)).toBe(true);
  });

  it("summarises at most 32 elements and scans long strings by prefix", () => {
    const long = Array.from({ length: 1000 }, (_, i) => (i < 32 ? 1 : -1));
    expect(shapeKey(long)).toBe("list|dups|elem:int|len:101-1000|order:sorted");
    expect(shapeKey("a".repeat(5000) + " ")).toBe("str|ascii|len:>1000|ws-edge");
  });
});

describe("stringKind", () => {
  it.each(STRING_KINDS)("%s", (text, kind) => {
    expect(stringKind(text)).toBe(kind);
  });
});

it("buckets lengths like pytest-coverset", () => {
  expect([0, 1, 2, 10, 11, 100, 101, 1000, 1001].map(lenBucket)).toEqual([
    "0", "1", "2-10", "2-10", "11-100", "11-100", "101-1000", "101-1000", ">1000",
  ]);
});
